package sfz.enc.l04.demo

import io.grpc.CallOptions
import io.grpc.Context
import io.grpc.StatusRuntimeException
import io.grpc.inprocess.InProcessChannelBuilder
import io.grpc.inprocess.InProcessServerBuilder
import java.util.concurrent.Executors
import java.util.concurrent.TimeUnit

/**
 * checkout -> payments -> issuer. The checkout sets a 300 ms deadline. Payments spends 120 ms on its own work,
 * then calls the issuer without setting any deadline. The issuer takes 500 ms. Who notices what, and when?
 */

private fun millisLeft(): String =
    Context.current().deadline?.let { "${it.timeRemaining(TimeUnit.MILLISECONDS)} ms left" } ?: "no deadline"

private fun since(t0: Long) = (System.nanoTime() - t0) / 1_000_000

fun main() {
    val pool = Executors.newCachedThreadPool()
    var t0 = System.nanoTime()

    // the issuer: slow today
    val authorize = method("issuer.v1.Cards", "Authorize")
    val issuerName = InProcessServerBuilder.generateName()
    val issuer = InProcessServerBuilder.forName(issuerName).executor(pool).addService(service(authorize) { request ->
        if (request == "warm-up") return@service "ok"
        println("%4d ms  issuer   got %s, %s".format(since(t0), request, millisLeft()))
        val ctx = Context.current()
        repeat(50) { if (!ctx.isCancelled) Thread.sleep(10) }
        println("%4d ms  issuer   %s".format(since(t0), if (ctx.isCancelled) "sees the call cancelled, stops" else "done"))
        "approved"
    }).build().start()
    val toIssuer = InProcessChannelBuilder.forName(issuerName).executor(pool).build()

    // payments: 120 ms of its own work, then the issuer, with no deadline of its own
    val charge = method("payments.v1.Charges", "Charge")
    val paymentsName = InProcessServerBuilder.generateName()
    val payments = InProcessServerBuilder.forName(paymentsName).executor(pool).addService(service(charge) { request ->
        if (request == "warm-up") return@service call(toIssuer, authorize, request)
        println("%4d ms  payments got %s, %s".format(since(t0), request, millisLeft()))
        Thread.sleep(120)
        try {
            call(toIssuer, authorize, request) // grpc-java passes the remaining deadline on by itself
        } catch (e: StatusRuntimeException) {
            println("%4d ms  payments issuer call ended: %s".format(since(t0), e.status.code))
            throw e
        }
    }).build().start()
    val toPayments = InProcessChannelBuilder.forName(paymentsName).build()

    call(toPayments, charge, "warm-up") // load the classes and open the channels first
    t0 = System.nanoTime()
    println("%4d ms  checkout calls payments with a 300 ms deadline".format(since(t0)))
    try {
        call(toPayments, charge, "pay-1", CallOptions.DEFAULT.withDeadlineAfter(300, TimeUnit.MILLISECONDS))
    } catch (e: StatusRuntimeException) {
        println("%4d ms  checkout gets %s".format(since(t0), e.status.code))
    }
    Thread.sleep(150) // let the issuer print what it saw

    toIssuer.shutdownNow(); toPayments.shutdownNow(); issuer.shutdownNow(); payments.shutdownNow(); pool.shutdownNow()
}

package sfz.enc.l04.demo

import io.grpc.EquivalentAddressGroup
import io.grpc.ManagedChannel
import io.grpc.NameResolver
import io.grpc.NameResolverProvider
import io.grpc.NameResolverRegistry
import io.grpc.netty.shaded.io.grpc.netty.NettyChannelBuilder
import io.grpc.netty.shaded.io.grpc.netty.NettyServerBuilder
import java.net.InetSocketAddress
import java.net.ServerSocket
import java.net.Socket
import java.net.SocketAddress
import java.net.URI
import java.util.concurrent.atomic.AtomicInteger
import kotlin.concurrent.thread

/**
 * Three replicas of a gRPC service on 127.0.0.1. 300 calls reach them three ways: through an L4 proxy that picks
 * a backend per TCP connection, through the same proxy from three channels, and with client-side round_robin.
 */

/** An L4 load balancer: picks the next backend for each new TCP connection, then only copies bytes. */
class L4Proxy(private val backends: List<Int>) : AutoCloseable {
    private val socket = ServerSocket(0)
    private val next = AtomicInteger()
    val port: Int get() = socket.localPort

    init {
        thread(isDaemon = true) {
            while (!socket.isClosed) {
                val client = try { socket.accept() } catch (e: Exception) { break }
                val backend = Socket("127.0.0.1", backends[next.getAndIncrement() % backends.size])
                pipe(client, backend); pipe(backend, client)
            }
        }
    }

    private fun pipe(from: Socket, to: Socket) = thread(isDaemon = true) {
        try { from.getInputStream().transferTo(to.getOutputStream()) } catch (e: Exception) { }
        runCatching { to.close() }; runCatching { from.close() }
    }

    override fun close() = socket.close()
}

/** A name that resolves to every replica's address, the way a headless Kubernetes Service does in DNS. */
class StaticResolver(private val addresses: List<SocketAddress>) : NameResolverProvider() {
    override fun isAvailable() = true
    override fun priority() = 5
    override fun getDefaultScheme() = "static"
    override fun newNameResolver(targetUri: URI, args: NameResolver.Args): NameResolver? =
        if (targetUri.scheme != "static") null else object : NameResolver() {
            override fun getServiceAuthority() = "charges"
            override fun start(listener: Listener2) {
                listener.onResult(
                    ResolutionResult.newBuilder().setAddressesOrError(
                        io.grpc.StatusOr.fromValue(addresses.map { EquivalentAddressGroup(it) }),
                    ).build(),
                )
            }
            override fun shutdown() {}
        }
}

fun main() {
    val m = method("payments.v1.Charges", "Charge")
    val counts = List(3) { AtomicInteger() }
    val servers = (0..2).map { i ->
        NettyServerBuilder.forAddress(InetSocketAddress("127.0.0.1", 0))
            .addService(service(m) { counts[i].incrementAndGet(); "ok from replica-${i + 1}" })
            .build().start()
    }
    fun report(label: String) {
        println("%-38s %s".format(label, counts.mapIndexed { i, c -> "replica-${i + 1}=${c.getAndSet(0)}" }.joinToString("  ")))
    }
    fun ManagedChannel.send(n: Int) = repeat(n) { call(this, m, "pay-$it") }

    L4Proxy(servers.map { it.port }).use { proxy ->
        val one = NettyChannelBuilder.forAddress("127.0.0.1", proxy.port).usePlaintext().build()
        one.send(300)
        report("one channel through the L4 proxy")
        one.shutdownNow()

        val three = List(3) { NettyChannelBuilder.forAddress("127.0.0.1", proxy.port).usePlaintext().build() }
        three.forEach { it.send(100) }
        report("three channels through the L4 proxy")
        three.forEach { it.shutdownNow() }
    }

    NameResolverRegistry.getDefaultRegistry().register(StaticResolver(servers.map { InetSocketAddress("127.0.0.1", it.port) }))
    val rr = NettyChannelBuilder.forTarget("static:///charges").defaultLoadBalancingPolicy("round_robin").usePlaintext().build()
    rr.send(300)
    report("one channel, client-side round_robin")
    rr.shutdownNow()

    servers.forEach { it.shutdownNow() }
}

package sfz.enc.l04.demo

import io.grpc.ServerServiceDefinition
import io.grpc.Status
import io.grpc.StatusRuntimeException
import io.grpc.inprocess.InProcessChannelBuilder
import io.grpc.inprocess.InProcessServerBuilder
import io.grpc.stub.ServerCalls
import java.util.UUID
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicInteger
import kotlin.random.Random

/**
 * 1,000 payments. For 30% of them the reply to the first attempt is lost after the card was charged.
 * The same server, four client behaviours. The server dedupes on the idempotency key when one arrives.
 */

private enum class Client { NO_RETRY, RETRY_NO_KEY, RETRY_NEW_KEY_EACH_TIME, RETRY_ONE_KEY }

private class Run(val charges: Int, val duplicates: Int, val reportedFailed: Int)

private fun run(mode: Client): Run {
    val unlucky = Random(42).let { rnd -> (1..1000).filter { rnd.nextDouble() < 0.30 }.map { "pay-$it" }.toSet() }
    val charges = ConcurrentHashMap<String, AtomicInteger>()
    val seenKeys = ConcurrentHashMap<String, String>()
    val arrived = ConcurrentHashMap<String, AtomicInteger>()
    val m = method("payments.v1.Charges", "Charge")
    val def = ServerServiceDefinition.builder(m.serviceName!!).addMethod(m, ServerCalls.asyncUnaryCall { req, reply ->
        val (paymentId, key) = req.split("|")
        val attempt = arrived.computeIfAbsent(paymentId) { AtomicInteger() }.incrementAndGet()
        val chargeId = if (key.isNotEmpty() && seenKeys.containsKey(key)) {
            seenKeys.getValue(key) // a replay: no new charge
        } else {
            charges.computeIfAbsent(paymentId) { AtomicInteger() }.incrementAndGet()
            "ch_$paymentId".also { if (key.isNotEmpty()) seenKeys[key] = it }
        }
        if (attempt == 1 && paymentId in unlucky) {
            reply.onError(Status.UNAVAILABLE.withDescription("reply lost").asRuntimeException())
        } else {
            reply.onNext(chargeId); reply.onCompleted()
        }
    }).build()
    val name = InProcessServerBuilder.generateName()
    val server = InProcessServerBuilder.forName(name).directExecutor().addService(def).build().start()
    val channel = InProcessChannelBuilder.forName(name).directExecutor().build()

    var failed = 0
    for (i in 1..1000) {
        val paymentId = "pay-$i"
        val oneKey = UUID.randomUUID().toString()
        var done = false
        for (attempt in 1..(if (mode == Client.NO_RETRY) 1 else 3)) {
            val key = when (mode) {
                Client.RETRY_ONE_KEY -> oneKey
                Client.RETRY_NEW_KEY_EACH_TIME -> UUID.randomUUID().toString()
                else -> ""
            }
            try { call(channel, m, "$paymentId|$key"); done = true; break } catch (e: StatusRuntimeException) { }
        }
        if (!done) failed++
    }
    channel.shutdownNow(); server.shutdownNow()
    val total = charges.values.sumOf { it.get() }
    return Run(total, total - charges.size, failed)
}

fun main() {
    println("%-26s %8s %11s %16s".format("client", "charges", "duplicates", "reported failed"))
    for (mode in Client.entries) {
        val r = run(mode)
        println("%-26s %8d %11d %16d".format(mode.name.lowercase().replace('_', ' '), r.charges, r.duplicates, r.reportedFailed))
    }
}

